WITH enriched AS (SELECT *, SUM(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, SUM(salary) OVER (ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary, STDDEV_SAMP(salary) OVER (PARTITION BY level) AS level_stddev_samp_salary, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary, id) AS seq_no FROM employees) SELECT seq_no, SORT_ARRAY(COLLECT_SET(level)) AS level_list, COUNT(CASE WHEN level = 'L2' THEN 1 END) AS l2_count, SORT_ARRAY(COLLECT_SET(level)) AS level_list_2, SIZE(COLLECT_SET(job_title)) AS num_job_titles FROM enriched GROUP BY seq_no ORDER BY seq_no DESC
